"use client";
import { useEffect, useRef, type ReactNode, type KeyboardEvent } from "react";
import { line, curveMonotoneX } from "d3-shape";
import "./shared/chip-option.css";
import "./chart-parts.css";
export type ChartSeries = { id: string; label: string; color?: string };
export type ChartDatum = {
  id: string;
  label: string;
  values: Record<string, number | undefined>;
  x?: number;
  event?: string;
};
export type ChartPart = {
  id: string;
  label: string;
  value: number;
  color?: string;
};
export const chartColor = (index: number) => `var(--chart-${(index % 6) + 1})`;
export const numberText = (value: number) =>
  new Intl.NumberFormat("en-US", { maximumFractionDigits: 2 }).format(value);
export function useChartReveal() {
  const root = useRef<HTMLElement>(null);
  useEffect(() => {
    const element = root.current;
    if (!element) return;
    const observer = new IntersectionObserver(
      (entries) => {
        if (entries[0].isIntersecting) {
          element.dataset.visible = "true";
          observer.disconnect();
        }
      },
      { threshold: 0.3 },
    );
    observer.observe(element);
    return () => observer.disconnect();
  }, []);
  return root;
}
export function ChartTable({
  label,
  headers,
  rows,
}: {
  label: string;
  headers: string[];
  rows: (string | number)[][];
}) {
  return (
    <div className="sr-only"><table>
      <caption>{label}</caption>
      <thead>
        <tr>
          {headers.map((header) => (
            <th key={header} scope="col">
              {header}
            </th>
          ))}
        </tr>
      </thead>
      <tbody>
        {rows.map((row, index) => (
          <tr key={index}>
            {row.map((cell, column) =>
              column === 0 ? (
                <th key={column} scope="row">
                  {cell}
                </th>
              ) : (
                <td key={column}>{cell}</td>
              ),
            )}
          </tr>
        ))}
      </tbody>
    </table></div>
  );
}
export function ChartMessage({
  loading,
  error,
  empty,
}: {
  loading?: boolean;
  error?: string;
  empty?: boolean;
}) {
  return error || empty ? (
    <p
      role="status"
      className="grid min-h-48 place-items-center text-sm text-muted-foreground"
    >
      {error ?? (loading ? "Loading chart…" : "No data for this range.")}
    </p>
  ) : loading ? (
    <p role="status" className="text-xs text-muted-foreground">
      Updating chart…
    </p>
  ) : null;
}
export function ChartLegend({
  series,
  hidden,
  onToggle,
  active,
  onActive,
}: {
  series: readonly ChartSeries[];
  hidden: readonly string[];
  onToggle: (id: string) => void;
  active?: string | null;
  onActive?: (id: string | null) => void;
}) {
  return (
    <div
      role="group"
      aria-label="Chart series"
      className="flex flex-wrap gap-2"
      onKeyDown={(event) => legendKeys(event)}
    >
      {series.map((item, index) => (
        <button
          key={item.id}
          type="button"
          data-slot="chart-legend-item"
          aria-pressed={!hidden.includes(item.id)}
          onClick={() => onToggle(item.id)}
          onPointerEnter={() => onActive?.(item.id)}
          onPointerLeave={() => onActive?.(null)}
          onFocus={() => onActive?.(item.id)}
          onBlur={() => onActive?.(null)}
          data-active={active === item.id}
        >
          <span
            aria-hidden="true"
            style={{ background: item.color ?? chartColor(index) }}
            className="size-2 rounded-full"
          />
          {item.label}
        </button>
      ))}
    </div>
  );
}
export function legendKeys(event: KeyboardEvent<HTMLElement>) {
  const nodes = [
    ...event.currentTarget.querySelectorAll<HTMLButtonElement>("button"),
  ];
  const index = nodes.indexOf(document.activeElement as HTMLButtonElement);
  const target =
    event.key === "Home"
      ? 0
      : event.key === "End"
        ? nodes.length - 1
        : ["ArrowRight", "ArrowDown"].includes(event.key)
          ? (index + 1) % nodes.length
          : ["ArrowLeft", "ArrowUp"].includes(event.key)
            ? (index - 1 + nodes.length) % nodes.length
            : -1;
  if (target >= 0) {
    event.preventDefault();
    nodes[target]?.focus();
  }
}
export function pointKey(
  event: KeyboardEvent<HTMLElement>,
  active: number | null,
  length: number,
) {
  const index = active ?? length - 1;
  const step = Math.max(1, Math.floor(length / 6));
  const next =
    event.key === "Home"
      ? 0
      : event.key === "End"
        ? length - 1
        : event.key === "PageUp"
          ? index + step
          : event.key === "PageDown"
            ? index - step
            : ["ArrowRight", "ArrowUp"].includes(event.key)
              ? index + 1
              : ["ArrowLeft", "ArrowDown"].includes(event.key)
                ? index - 1
                : event.key === "Escape"
                  ? null
                  : undefined;
  if (next !== undefined) event.preventDefault();
  return next == null ? next : Math.max(0, Math.min(length - 1, next));
}
export function pathFor(
  data: readonly ChartDatum[],
  id: string,
  minimum: number,
  maximum: number,
  hidden = false,
) {
  if (!data.length) return "";
  const first = data[0].x ?? 0,
    last = data[data.length - 1].x ?? data.length - 1;
  const points = data.map((item, index) => ({
    x: (600 * ((item.x ?? index) - first)) / (last - first || 1),
    y: item.values[id],
  }));
  // Monotone cubic tangents (Fritsch-Carlson): the line is smooth through every point and never overshoots it.
  const ok = (value: number | undefined): value is number => value !== undefined && Number.isFinite(value);
  const slope = (k: number) => {
    const p = points[k], q = points[k + 1];
    return p && q && ok(p.y) && ok(q.y) ? (q.y - p.y) / (q.x - p.x || 1) : Number.NaN;
  };
  const tangents = points.map((_, k) => {
    const before = slope(k - 1), after = slope(k);
    if (!Number.isFinite(before)) return Number.isFinite(after) ? after : 0;
    if (!Number.isFinite(after)) return before;
    return before * after <= 0 ? 0 : (2 * before * after) / (before + after);
  });
  const samples = Array.from({ length: 97 }, (_, index) => {
    const x = (index / 96) * 600;
    let right = points.findIndex((point) => point.x >= x);
    if (right < 0) right = points.length - 1;
    const left = Math.max(0, right - 1);
    const a = points[left],
      b = points[right];
    const valid = ok(a.y) && ok(b.y);
    const h = b.x - a.x || 1;
    const t = Math.min(1, Math.max(0, (x - a.x) / h));
    const value = valid
      ? (2 * t ** 3 - 3 * t ** 2 + 1) * a.y! + (t ** 3 - 2 * t ** 2 + t) * h * tangents[left]! + (-2 * t ** 3 + 3 * t ** 2) * b.y! + (t ** 3 - t ** 2) * h * tangents[right]!
      : Number.NaN;
    return [
      x,
      hidden ? 210 : 210 - ((value - minimum) / (maximum - minimum || 1)) * 200,
    ] as [number, number];
  });
  return (
    line<[number, number]>()
      .defined((point) => Number.isFinite(point[1]))
      .x((point) => point[0])
      .y((point) => point[1])
      .curve(curveMonotoneX)(samples) ?? ""
  );
}
export function ChartReadout({ children }: { children: ReactNode }) {
  return (
    <div
      data-slot="chart-readout"
      aria-hidden="true"
      className="mt-3 min-h-11 rounded-surface bg-surface px-3 py-2 text-xs leading-5"
    >
      {children}
    </div>
  );
}

import { clsx, type ClassValue } from "clsx";
import { extendTailwindMerge } from "tailwind-merge";

const twMerge = extendTailwindMerge({
  extend: { theme: { radius: ["control", "surface", "overlay"], shadow: ["overlay"] } },
});

export function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs));
}

"use client";
import { area, curveMonotoneX } from "d3-shape";
import { useState, type CSSProperties } from "react";
import { cn } from "./lib/cn";
import {
  ChartTable,
  ChartMessage,
  ChartLegend,
  ChartReadout,
  chartColor,
  numberText,
  pathFor,
  pointKey,
  useChartReveal,
  type ChartDatum,
  type ChartSeries,
} from "./chart-parts";
import "./shared/chart-crosshair.css";
import "./line-chart.css";
export type LineChartProps = {
  label: string;
  data: readonly ChartDatum[];
  series: readonly ChartSeries[];
  unit?: string;
  loading?: boolean;
  error?: string;
  className?: string;
  band?: { lower: string; upper: string };
};
export function LineChart({
  label,
  data,
  series,
  unit = "",
  loading,
  error,
  className,
  band,
}: LineChartProps) {
  const root = useChartReveal();
  const [hidden, setHidden] = useState<string[]>([]),
    [reading, setReading] = useState<number | null>(null);
  const visible = series.filter((item) => !hidden.includes(item.id));
  const values = data.flatMap((item) =>
    visible
      .map((s) => item.values[s.id])
      .filter(
        (value): value is number =>
          value !== undefined && Number.isFinite(value),
      ),
  );
  const extremes = band
    ? data.flatMap((item) => [
        item.values[band.lower] ?? 0,
        item.values[band.upper] ?? 0,
      ])
    : values;
  const min = Math.min(0, ...extremes),
    max = Math.max(1, ...extremes);
  const index = reading === null ? null : Math.min(reading, data.length - 1);
  const datum = index === null ? null : data[index];
  function scrub(clientX: number, rect: DOMRect) {
    if (!data.length) return;
    const ratio = Math.max(0, Math.min(1, (clientX - rect.left) / rect.width));
    const first = data[0].x ?? 0,
      last = data.at(-1)?.x ?? data.length - 1;
    let nearest = 0;
    data.forEach((item, i) => {
      if (
        Math.abs((item.x ?? i) - (first + ratio * (last - first))) <
        Math.abs(
          (data[nearest].x ?? nearest) - (first + ratio * (last - first)),
        )
      )
        nearest = i;
    });
    setReading(nearest);
  }
  const text = datum
    ? `${datum.label}. ${visible.map((item) => `${item.label}: ${datum.values[item.id] === undefined ? "No reading" : numberText(datum.values[item.id]!)} ${unit}`).join(". ")}${datum.event ? `. ${datum.event}` : ""}`
    : label;
  return (
    <figure
      ref={root}
      aria-label={label}
      data-slot="line-chart"
      aria-busy={loading}
      className={cn("min-w-0", className)}
    >
      <figcaption className="mb-3 text-sm font-medium">{label}</figcaption>
      <ChartLegend
        series={series}
        hidden={hidden}
        onToggle={(id) =>
          setHidden(
            hidden.includes(id)
              ? hidden.filter((key) => key !== id)
              : [...hidden, id],
          )
        }
      />
      <ChartMessage loading={loading} error={error} empty={!data.length} />
      {!error && !!data.length && (
        <>
          <div className="relative mt-4 pl-9" data-slot="chart-frame">
            <div
              className="absolute inset-y-0 left-0 flex flex-col justify-between pb-7 text-[11px] tabular-nums text-muted-foreground"
              aria-hidden="true"
            >
              <span>{numberText(max)}</span>
              <span>{numberText((max + min) / 2)}</span>
              <span>{numberText(min)}</span>
            </div>
            <div
              role="slider"
              tabIndex={0}
              aria-label={`${label}, explore points`}
              aria-valuemin={0}
              aria-valuemax={data.length - 1}
              aria-valuenow={index ?? data.length - 1}
              aria-valuetext={text}
              data-slot="chart-plot"
              className="relative touch-pan-y outline-none focus-visible:outline-solid focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-ring"
              onFocus={() => setReading(data.length - 1)}
              onBlur={() => setReading(null)}
              onKeyDown={(event) => {
                const next = pointKey(event, index, data.length);
                if (next !== undefined) setReading(next);
              }}
              onPointerMove={(event) => {
                if (
                  event.pointerType === "mouse" ||
                  event.currentTarget.hasPointerCapture(event.pointerId)
                )
                  scrub(
                    event.clientX,
                    event.currentTarget.getBoundingClientRect(),
                  );
              }}
              onPointerDown={(event) => {
                event.currentTarget.setPointerCapture(event.pointerId);
                scrub(
                  event.clientX,
                  event.currentTarget.getBoundingClientRect(),
                );
              }}
              onPointerLeave={(event) => {
                if (
                  !event.currentTarget.hasPointerCapture(event.pointerId) &&
                  document.activeElement !== event.currentTarget
                )
                  setReading(null);
              }}
              onPointerUp={(event) => {
                event.currentTarget.releasePointerCapture(event.pointerId);
                if (event.pointerType !== "mouse") setReading(null);
              }}
            >
              <svg
                aria-hidden="true"
                viewBox="0 0 600 220"
                className="block h-52 w-full overflow-visible"
                preserveAspectRatio="none"
              >
                {[10, 110, 210].map((y) => (
                  <line
                    key={y}
                    x1="0"
                    x2="600"
                    y1={y}
                    y2={y}
                    stroke="var(--border)"
                    strokeDasharray="2 4"
                  />
                ))}
                {band && (
                  <path
                    fill="var(--chart-1)"
                    opacity=".12"
                    d={
                      area<ChartDatum>()
                        .x(
                          (item, i) =>
                            (600 * ((item.x ?? i) - (data[0].x ?? 0))) /
                            ((data.at(-1)?.x ?? data.length - 1) -
                              (data[0].x ?? 0) || 1),
                        )
                        .y0(
                          (item) =>
                            210 -
                            (((item.values[band.lower] ?? 0) - min) /
                              (max - min)) *
                              200,
                        )
                        .y1(
                          (item) =>
                            210 -
                            (((item.values[band.upper] ?? 0) - min) /
                              (max - min)) *
                              200,
                        )
                        .curve(curveMonotoneX)([...data]) ?? ""
                    }
                  />
                )}
                {series[0] && !hidden.includes(series[0].id) && (() => {
                  // A soft wash under the lead series gives the chart weight without a second colour.
                  const line = pathFor(data, series[0].id, min, max);
                  const d = line ? `${line}L600,210L0,210Z` : "";
                  return <path data-slot="chart-wash" d={d} style={{ d: `path("${d}")` } as CSSProperties} fill={series[0].color ?? chartColor(0)} stroke="none" aria-hidden="true" />;
                })()}
                {series.map((item, i) => {
                  const d = pathFor(
                    data,
                    item.id,
                    min,
                    max,
                    hidden.includes(item.id),
                  );
                  return (
                    <path
                      key={item.id}
                      data-slot="chart-line"
                      d={d}
                      style={
                        {
                          d: `path("${d}")`,
                          opacity: hidden.includes(item.id) ? 0.12 : 1,
                        } as CSSProperties
                      }
                      fill="none"
                      stroke={item.color ?? chartColor(i)}
                      strokeWidth="2"
                      vectorEffect="non-scaling-stroke"
                      pathLength="1"
                    />
                  );
                })}
                {datum && (
                  <g
                    data-slot="chart-crosshair"
                    style={{
                      transform: `translateX(${(600 * ((datum.x ?? index!) - (data[0].x ?? 0))) / ((data.at(-1)?.x ?? data.length - 1) - (data[0].x ?? 0) || 1)}px)`,
                    }}
                  >
                    <line
                      y1="0"
                      y2="220"
                      stroke="var(--muted-foreground)"
                      strokeDasharray="3 3"
                    />
                    {visible.map(
                      (item, i) =>
                        datum.values[item.id] !== undefined && (
                          <circle
                            key={item.id}
                            cy={
                              210 -
                              ((datum.values[item.id]! - min) / (max - min)) *
                                200
                            }
                            r="4"
                            fill={item.color ?? chartColor(i)}
                            stroke="var(--elevated)"
                            strokeWidth="2"
                          />
                        ),
                    )}
                  </g>
                )}
                {data.map(
                  (item, i) =>
                    item.event && (
                      <circle
                        key={item.id}
                        cx={(600 * i) / (data.length - 1 || 1)}
                        cy="220"
                        r="3"
                        fill="var(--chart-2)"
                      />
                    ),
                )}
              </svg>
            </div>
            <div
              aria-hidden="true"
              className="mt-2 flex justify-between gap-3 text-[11px] text-muted-foreground"
            >
              <span>{data[0].label}</span>
              <span>{data.at(-1)?.label}</span>
            </div>
          </div>
          <ChartReadout>
            {datum ? (
              <>
                <span className="font-medium">{datum.label}</span>
                <div className="flex flex-wrap gap-x-4">
                  {visible.map((item) => (
                    <span key={item.id}>
                      {item.label}{" "}
                      <strong className="font-medium tabular-nums">
                        {datum.values[item.id] === undefined
                          ? "—"
                          : numberText(datum.values[item.id]!)}{" "}
                        {unit}
                      </strong>
                    </span>
                  ))}
                  {datum.event && <span>{datum.event}</span>}
                </div>
              </>
            ) : (
              <span className="text-muted-foreground">
                Hover, drag, or use arrow keys to read a point.
                {!visible.length ? " All series hidden." : ""}
              </span>
            )}
          </ChartReadout>
        </>
      )}
      <ChartTable
        label={label}
        headers={["Point", ...series.map((item) => item.label), "Event"]}
        rows={data.map((item) => [
          item.label,
          ...series.map((s) => item.values[s.id] ?? "—"),
          item.event ?? "",
        ])}
      />
    </figure>
  );
}

/* Shared by calendar.tsx, chart-parts.tsx, chip-group.tsx, data-table.tsx, number-field.tsx, password-field.tsx, stepper.tsx; each imports it. Edit freely. */
@layer theme, base, components, utilities;

@layer components {
  /* Depth sets 2 and 3 end */

  /* Press feedback (2026-10-20, motion audit): every pressable control answers a press. Compact controls take the
     system press scale, as Button does; wide rows deepen their fill instead, since scaling a full-width row reads as a
     jump. Disabled controls stay still. */
  :is([data-slot="chip-option"], [data-slot="number-field"] button, [data-slot="password-toggle"], [data-slot="calendar"] button, [data-slot="chart-legend-item"], [data-slot="sort-button"], [data-slot="stepper"] button):active:not(:disabled):not([aria-disabled="true"]) {
    scale: var(--motion-press-scale);
  }
}

/* chart-parts.tsx's styles; it imports this file. Edit freely. */
@layer theme, base, components, utilities;

@layer components {
  [data-slot="chart-legend-item"] {
    display: inline-flex;
    align-items: center;
    gap: 0.5rem;
    min-height: var(--control-height);
    padding: 0.25rem 0.5rem;
    border-radius: var(--radius-control);
    font-size: 0.75rem;
    color: var(--muted-foreground);
    outline: none;
    transition:
      background-color var(--duration-fast) var(--ease-out),
      color var(--duration-fast) var(--ease-out);
  }
  [data-slot="chart-legend-item"]:hover,
  [data-slot="chart-legend-item"][data-active="true"] {
    background: var(--muted);
    color: var(--foreground);
  }
  [data-slot="chart-legend-item"]:focus-visible {
    outline: 2px solid var(--ring);
    outline-offset: 2px;
  }
  [data-slot="chart-legend-item"][aria-pressed="false"] {
    opacity: 0.45;
    text-decoration: line-through;
  }
}

/* Shared by line-chart.tsx, market-terminal.tsx, price-target-fan.tsx, revenue-explorer.tsx, ridgeline.tsx, streamgraph.tsx; each imports it. Edit freely. */
@layer theme, base, components, utilities;

@layer components {
  [data-slot="chart-crosshair"] {
    transition: transform var(--duration-fast) var(--ease-out);
  }
  @media (prefers-reduced-motion: reduce) {
    [data-slot="chart-crosshair"] {
      transition: none;
      animation: none !important;
    }
  }
}

/* line-chart.tsx's styles; it imports this file. Edit freely. */
@layer theme, base, components, utilities;

@layer components {
  [data-slot="chart-line"],
  [data-slot="chart-wash"] {
    transition:
      d var(--duration-travel) var(--ease-showcase),
      opacity var(--duration-normal) var(--ease-out);
  }
  [data-slot="chart-wash"] { opacity: 0.1; }
  [data-slot="line-chart"][data-visible="true"] [data-slot="chart-wash"] {
    animation: caliper-chart-fade var(--duration-showcase) var(--ease-out);
  }
  [data-slot="line-chart"][data-visible="true"] [data-slot="chart-line"] {
    animation: caliper-chart-draw var(--duration-showcase) var(--ease-showcase);
  }
  @media (prefers-reduced-motion: reduce) {
    [data-slot="chart-line"] {
      transition: none;
      animation: none !important;
    }
  }
  [data-slot="line-chart"][aria-busy="true"] [data-slot="chart-plot"] {
    opacity: 0.5;
  }
}
